def main():
    assert len(C) == 100, len(C)
    clips, prev = [], "standoff"
    for i, (sid, camera, action, beats, chg) in enumerate(C):
        s, p = SETS[sid], SETS[prev]
        if chg is not None:
            t = f"00:{int(chg):02d}" + (".5" if chg % 1 else "")
            env = f"{p['env']} -- then -- {s['env']}"
            cast = f"{p['cast']} (until {t}); then {s['cast']}"
            light = f"{p['light']}; then {s['light']}"
            neg = ", ".join(x for x in (p.get("neg"), s.get("neg")) if x)
            rigid = "; ".join(x for x in (p.get("rigid"), s.get("rigid")) if x)
        else:
            env, cast, light, neg, rigid = s["env"], s["cast"], s["light"], s.get("neg"), s.get("rigid")
        clip = {"env": env, "cast": cast, "action": action, "camera": camera, "lighting": light,
                "beats": [list(b) for b in beats]}
        if chg is not None:
            clip["change_at"] = chg
        if neg:
            clip["neg"] = neg
        if rigid:
            clip["rigid"] = rigid
        clips.append(clip)
        prev = sid
    plan = {"tag": "CH02EP16", "look": "ch02", "start": 13, "clips": clips}
    p = HERE / "CH02EP16_omni_plan_013-112.json"
    p.write_text(json.dumps(plan, ensure_ascii=False, indent=1), encoding="utf-8")
    render = HERE / "_rx_omni_render.py"
    if not render.exists():
        render = HERE.parent / "_rx_omni_render.py"
    subprocess.run([sys.executable, str(render), str(p)], check=True)


if __name__ == "__main__":
    main()
